import cn from 'classnames'
import {
  ComponentPropsWithoutRef,
  ForwardedRef,
  forwardRef,
  MouseEvent,
  ReactNode,
} from 'react'
import { Link } from '../../links'
import { Tag } from '../../tag'
import styles from './SimpleCard.module.css'

export type SimpleCardDataTestId = {
  root?: string
  title?: string
  tags?: string
  logos?: string
  description?: string
}

export type SimpleCardProps = ComponentPropsWithoutRef<'div'> & {
  featuredText?: string
  title: string
  text: string
  href?: string
  titleImg: ReactNode
  tags?: string[]
  logosArray?: string[]
  maxLogosAmount?: number
  learnMoreLink?: string
  dataTestId?: SimpleCardDataTestId
  onLearnMoreClick?: () => void
}

export const SimpleCard = forwardRef(
  (
    {
      title,
      text,
      titleImg,
      featuredText,
      tags,
      logosArray,
      href,
      dataTestId,
      learnMoreLink,
      maxLogosAmount = 2,
      className,
      onLearnMoreClick,
      onClick,
      ...rest
    }: SimpleCardProps,
    ref?: ForwardedRef<HTMLDivElement> | ForwardedRef<HTMLAnchorElement>,
  ) => {
    const logosToShow = logosArray?.slice(0, maxLogosAmount)
    const logosHidden = logosArray
      ? Math.max(logosArray?.length - maxLogosAmount, 0)
      : 0

    const cardContents = (
      <>
        <div className={styles.header}>
          {titleImg && <div className={styles.titleImage}>{titleImg}</div>}
          {featuredText && (
            <Tag
              className={styles.featuredTag}
              variant='primary'
              color='highlighted'
            >
              {featuredText}
            </Tag>
          )}
          <div className={styles.headerLogos} data-testid={dataTestId?.logos}>
            {logosToShow?.map((logo, index) => (
              <div key={index} className={styles.headerLogo}>
                <img src={logo} width={38} height={38} alt={''} />
              </div>
            ))}
            {logosHidden ? (
              <div className={cn(styles.headerLogo, styles.empty)}>
                <span>+{logosHidden}</span>
              </div>
            ) : (
              <></>
            )}
          </div>
        </div>
        <div className={styles.titleItem} data-testid={dataTestId?.title}>
          {title}
        </div>
        <div
          className={styles.descriptionItem}
          data-testid={dataTestId?.description}
        >
          {text}
          {learnMoreLink && (
            <Link
              target='_blank'
              href={learnMoreLink}
              onClick={() => onLearnMoreClick?.()}
            >
              &nbsp;Learn more
            </Link>
          )}
        </div>
        {tags?.length && (
          <div className={styles.tags} data-testid={dataTestId?.tags}>
            {tags?.map((tag) => (
              <Tag key={tag} variant={'primary'}>
                {tag}
              </Tag>
            ))}
          </div>
        )}
      </>
    )
    return href ? (
      <Link
        href={href}
        target={'_blank'}
        className={cn(className, styles.card)}
        data-testid={dataTestId?.root}
        ref={ref as ForwardedRef<HTMLAnchorElement>}
        onClick={(e) => onClick?.(e as unknown as MouseEvent<HTMLDivElement>)}
      >
        {cardContents}
      </Link>
    ) : (
      <div
        className={cn(className, styles.card)}
        data-testid={dataTestId?.root}
        {...rest}
        ref={ref as ForwardedRef<HTMLDivElement>}
      >
        {cardContents}
      </div>
    )
  },
)

SimpleCard.displayName = 'SimpleCard'
